import spidev
import time
import signal
import sys
import logging
import threading
import picamera2
import adafruit_hcsr04
import paho.mqtt.client as mqtt
import gpiozero
from gpiozero import Button
from gpiozero.pins.pigpio import PiGPIOFactory
from gpiozero.pins.pigpio import Pin

# Set up logging
logging.basicConfig(level=logging.INFO)

# Set up GPIO
factory = PiGPIOFactory()
gpiozero.Device.pin_factory = factory

# Set up SPI
spi = None

def signal_handler(sig, frame):
    """Handler for SIGTERM signal."""
    global spi
    if spi is not None:
        spi.close()
    sys.exit(0)

def send_spi_command(spi, data):
    """Send a command to the SPI device and return the response."""
    try:
        return spi.xfer2(data)
    except (OSError, IOError) as e:
        logging.error(f"SPI transfer failed: {e}")
        raise

def extract_10bit(response):
    """Extract a 10-bit value from the response."""
    return ((response[1] & 0x03) << 8) | response[2]

class LoadCellReader:
    def __init__(self):
        """Initialize the LoadCellReader."""
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)  # Open SPI0/CE0 (/dev/spidev0.0)
        self.spi.max_speed_hz = 50000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def read_raw_data(self):
        """Read the raw data from the load cell."""
        try:
            response = send_spi_command(self.spi, [0x01, 0x80, 0x00])
            return extract_10bit(response)
        except (OSError, IOError) as e:
            logging.error(f"Failed to read raw data: {e}")
            return None

    def convert_to_weight(self, raw_data):
        """Convert the raw data to weight."""
        if raw_data is not None:
            return float(raw_data) * (5.0 / 1023.0)
        else:
            return None

    def close(self):
        """Close the SPI device."""
        if self.spi is not None:
            self.spi.close()

    def run(self):
        """Run the LoadCellReader."""
        while True:
            try:
                raw_data = self.read_raw_data()
                weight = self.convert_to_weight(raw_data)
                if weight is not None:
                    logging.info(f"Weight: {weight:.2f} kg")
                time.sleep(0.5)
            except (KeyboardInterrupt, SystemExit):
                self.close()
                logging.info("Shutdown complete.")
                break
            except Exception as e:
                logging.error(f"Error: {e}")
                self.close()
                break

def main():
    """Main entry point."""
    signal.signal(signal.SIGTERM, signal_handler)
    load_cell_reader = LoadCellReader()
    try:
        load_cell_reader.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        load_cell_reader.close()
        sys.exit(1)

if __name__ == "__main__":
    main()

