import argparse
import logging
import logging.handlers
import queue
import spidev
import RPi.GPIO as GPIO
import time
import threading
import picamera2
import paho.mqtt.client as mqtt
import gpiozero
from gpiozero import DigitalInputDevice
from gpiozero.pins.pigpio import PiGPIOFactory
from adafruit_mcp3008 import MCP3008

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
handler = logging.handlers.RotatingFileHandler('sound_sensor.log', maxBytes=1000000, backupCount=1)
logger.addHandler(handler)

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.last_event_time = 0

        if self.sensor_type == 'digital':
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        elif self.sensor_type == 'analog':
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.mcp3008 = MCP3008(self.spi, cs=None)
            except Exception as e:
                logger.error(f"Failed to initialize SPI: {e}")
                raise

    def read_analog(self):
        try:
            result = self.mcp3008.read(self.channels[0])
            return (result >> 2) & 0x3FF
        except Exception as e:
            logger.error(f"Failed to read analog value: {e}")
            return None

    def read_digital(self):
        for pin in self.gpio_pins:
            if GPIO.input(pin) == 1:
                return True
        return False

    def detect_event(self):
        if self.sensor_type == 'digital':
            return self.read_digital()
        elif self.sensor_type == 'analog':
            return self.read_analog() >= self.threshold

    def run(self):
        self.running = True
        while self.running:
            if self.detect_event():
                if time.time() - self.last_event_time >= 0.1:
                    self.last_event_time = time.time()
                    self.log_queue.put(f"Sound detected on sensor {self.sensor_id}")
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.running = False
        if self.sensor_type == 'digital':
            GPIO.cleanup()
        elif self.sensor_type == 'analog':
            self.spi.close()

def main():
    parser = argparse.ArgumentParser(description='Sound sensor')
    parser.add_argument('--sensor_type', type=str, default='digital', choices=['digital', 'analog'])
    parser.add_argument('--threshold', type=int, default=500)
    parser.add_argument('--sample_rate', type=int, default=1)
    parser.add_argument('--log_file', type=str, default='sound_sensor.log')
    parser.add_argument('--gpio_pins', type=int, nargs='+', default=[17])
    parser.add_argument('--channels', type=int, nargs='+', default=[0])
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', type=int, nargs='+', default=[1])
    args = parser.parse_args()

    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
        sensors.append(sensor)

    def log_thread():
        while True:
            try:
                log = log_queue.get(timeout=1)
                logger.info(log)
            except queue.Empty:
                pass

    log_thread = threading.Thread(target=log_thread)
    log_thread.daemon = True
    log_thread.start()

    client = mqtt.Client()
    client.connect("localhost")

    for sensor in sensors:
        sensor_thread = threading.Thread(target=sensor.run)
        sensor_thread.daemon = True
        sensor_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        client.disconnect()

if __name__ == "__main__":
    main()

