import logging
import sys
import signal
import time
import gpiozero
from gpiozero import DistanceSensor, AngularServo
from picamera2 import Picamera2
from adafruit_circuitpython_pca9685 import PCA9685
import paho.mqtt.client as mqtt

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class BalanceBeamController:
    def __init__(self):
        self.servo = AngularServo(25, min_pulse_width=0.5, max_pulse_width=2.5, frame_width=20, min_angle=0, max_angle=50)
        self.sensor = DistanceSensor(trigger=23, echo=24, max_distance=100)
        self.pca = PCA9685()
        self.pca.frequency = 60
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.connect("localhost")
        self.balance_time = 0
        self.consecutive_in_range = 0
        self.max_error = 25
        self.setpoint = 25
        self.gains = {"P": 0.5, "I": 0.00, "D": 0.4}
        self.error_integral = 0
        self.error_previous = 0
        self.error_derivative = 0

    def pid_update(self):
        try:
            distance = self.sensor.distance
            error = self.setpoint - distance
            if abs(error) > self.max_error:
                logger.warning(f"Error exceeded max error: {error} cm")
                return
            self.error_integral += error * 0.1
            self.error_derivative = (error - self.error_previous) / 0.1
            self.error_previous = error
            servo_command = self.gains["P"] * error + self.gains["I"] * self.error_integral + self.gains["D"] * self.error_derivative
            self.servo.value = servo_command
            logger.info(f"Distance: {distance} cm, Error: {error} cm, Servo: {servo_command} degrees")
            if abs(error) <= 3:
                self.consecutive_in_range += 1
                if self.consecutive_in_range >= 3:
                    self.balance_time = time.time()
            else:
                self.consecutive_in_range = 0
        except gpiozero.exceptions.GPIOPinValueError as e:
            logger.error(f"Sensor read failed: {e}")
            time.sleep(0.1)
        except Exception as e:
            logger.error(f"PID update failed: {e}")

    def run(self):
        try:
            while True:
                self.pid_update()
                if time.time() - self.balance_time >= 3:
                    self.detach_servo()
                    break
                time.sleep(0.1)
        except KeyboardInterrupt:
            self.detach_servo()
            self.sensor.close()
            self.pca.deinit()
            self.mqtt_client.disconnect()
            sys.exit(0)

    def detach_servo(self):
        try:
            self.servo.detach()
        except Exception as e:
            logger.error(f"Failed to detach servo: {e}")

    def close_sensor(self):
        try:
            self.sensor.close()
        except Exception as e:
            logger.error(f"Failed to close sensor: {e}")

    def close_pca(self):
        try:
            self.pca.deinit()
        except Exception as e:
            logger.error(f"Failed to close PCA: {e}")

    def close_mqtt(self):
        try:
            self.mqtt_client.disconnect()
        except Exception as e:
            logger.error(f"Failed to close MQTT: {e}")

def signal_handler(sig, frame):
    controller.detach_servo()
    controller.close_sensor()
    controller.close_pca()
    controller.close_mqtt()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    controller = BalanceBeamController()
    controller.run()

