import picamera2
import picamera2.controls
import gpiozero
import adafruit_mqtt
import paho.mqtt.client as mqtt
from flask import Flask, render_template, request, Response
from config import config
from mail_config import mail_config
from PIL import Image
from io import BytesIO
import numpy as np
import cv2
import tensorflow as tf

# Set up logging
logging.basicConfig(level=logging.INFO)

# Set up signal handlers
def signal_handler(sig, frame):
    logging.info('Received signal %s, shutting down', sig)
    camera.stop_preview()
    camera.close()
    sys.exit(0)

def exit_handler():
    logging.info('Exiting normally')
    camera.stop_preview()
    camera.close()

atexit.register(exit_handler)
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Set up camera
camera = None
try:
    camera = picamera2.Picamera2()
    camera.configure(picamera2.PreviewConfiguration.make_default())
    camera.start_preview()
except Exception as e:
    logging.error('Failed to initialize camera: %s', e)
    sys.exit(1)

# Set up classifier
classifiers = {
    'yolov3': tf.keras.models.load_model('yolov3.h5'),
    'yolov4': tf.keras.models.load_model('yolov4.h5'),
    'motion_detector': None
}

# Set up email
email_client = None
if mail_config.email_enabled:
    email_client = mqtt.Client()
    email_client.connect(mail_config.email_broker)

# Set up GPIO
led = gpiozero.LED(config.led_pin)

app = Flask(__name__)

class Camera:
    def __init__(self):
        self.camera = camera
        self.transform = picamera2.Picamera2ControlValue(
            'transform', picamera2.Picamera2ControlValueTransform(
                rotation=0, flip=picamera2.Picamera2ControlValueFlip.VERTICAL
            )
        )

    def get_frame(self):
        try:
            frame = self.camera.capture_array(self.transform)
            frame = np.frombuffer(frame, dtype=np.uint8).reshape((480, 640, 3))
            return cv2.imencode('.jpg', frame)[1].tobytes()
        except Exception as e:
            logging.error('Failed to capture frame: %s', e)
            return b''

    def get_object(self, classifier):
        try:
            frame = self.get_frame()
