        'level': 'INFO',
        'handlers': ['console', 'file']
    }
})

# Define a context manager for closing the image file handle
@contextmanager
def image_file(file_path):
    try:
        with open(file_path, 'rb') as file:
            yield Image.open(file)
    finally:
        file.close()

class Frame:
    def __init__(self, image, duration, loop):
        self.image = image
        self.duration = duration
        self.loop = loop

class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder='.'):
        self._display = display
        self._width = width or display.width
        self._height = height or display.height
        self._folder = folder
        self._files = []
        self._current_file_index = 0
        self._is_running = False
        self._loop_count = 0
        self._loop = 0
        self._frame = None
        self._last_display_time = time.monotonic()
        self._display_button = Button(17)
        self._display_button.when_pressed = self._stop

    def load_files(self):
        self._files = []
        for file in os.listdir(self._folder):
            if file.endswith('.gif'):
                try:
                    with image_file(os.path.join(self._folder, file)) as img:
                        if img.is_animated:
                            self._files.append(file)
                except Exception as e:
                    logging.warning(f"Skipping {file}: {e}")
        if not self._files:
            raise FileNotFoundError("No valid GIF files found")

    def preload(self):
        try:
            with image_file(os.path.join(self._folder, self._files[self._current_file_index])) as img:
                self._loop = img.info.get('loop', 0)
                self._loop_count = self._loop if self._loop > 0 else float('inf')
                self._frames = []
                for i in range(img.n_frames):
                    img.seek(i)
                    duration = img.info.get('duration', 0)
                    self._frames.append(Frame(img.copy(), duration, self._loop))
                self._frame = self._frames[0]
        except Exception as e:
            logging.error(f"Error preloading {self._files[self._current_file_index]}: {e}")

    def play(self):
        if not self._frame:
            self.preload()
        if self._loop_count > 0:
            self._loop_count -= 1
        self._display.display(self._frame.image)
        elapsed_time = time.monotonic() - self._last_display_time
        sleep_time = max(0, self._frame.duration / 1000 - elapsed_time)
        time.sleep(sleep_time)
        self._last_display_time = time.monotonic()
        if self._loop_count == 0:
            return True
        self._frame = self._frames[(self._frames.index(self._frame) + 1) % len(self._frames)]
        return False

    def run(self):
        self.load_files()
        self._is_running = True
        while self._is_running:
            try:
                if not self.play():
                    self._current_file_index = (self._current_file_index + 1) % len(self._files)
                    self.preload()
            except Exception as e:
                logging.error(f"Error running animation: {e}")
                self._is_running = False

    def stop(self):
        self._is_running = False

    def display(self, img):
        self._display.display(img)

    def advance(self):
        self._current_file_index = (self._current_file_index + 1) % len(self._files)
        self.preload()

def signal_handler(sig, frame):
    logging.info("Shutting down")
    animated_gif.stop()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

