import gpiozero
import picamera2
import adafruit_dht
import adafruit_bme280
import paho.mqtt.client as mqtt
import subprocess
import logging
import time
import sys
import signal
import datetime

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s: %(message)s')
logger = logging.getLogger()

def simulate_light_sensor(pin):
    """Simulate light sensor readings based on time of day."""
    current_time = datetime.datetime.now()
    if 6 <= current_time.hour < 18:
        return gpiozero.RoboLinkAnalogInputDevice(pin, pull_up=False, min_value=600, max_value=1000)
    else:
        return gpiozero.RoboLinkAnalogInputDevice(pin, pull_up=False, min_value=100, max_value=300)

def simulate_temperature_sensor(pin):
    """Simulate temperature sensor readings."""
    return gpiozero.RoboLinkAnalogInputDevice(pin, pull_up=False, min_value=20, max_value=30)

def read_pi_temperature():
    """Read Raspberry Pi's internal temperature via vcgencmd."""
    try:
        output = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=1)
        if output.returncode == 0:
            return float(output.stdout.strip().split('=')[1])
        else:
            logger.warning("Failed to read Pi temperature")
            return None
    except Exception as e:
        logger.warning(f"Failed to read Pi temperature: {e}")
        return None

def log_reading(light, temperature, voltage, current, pi_temperature):
    """Log a single reading."""
    logger.info(f"Light: {light} lux, Temperature: {temperature}°C, Voltage: {voltage}V, Current: {current}A, Pi Temperature: {pi_temperature}°C")

def threshold_actions(light, temperature, voltage, current, pi_temperature):
    """Trigger threshold actions."""
    if light < 300:
        logger.warning("Possible solar panel performance issues")
    if temperature > 35:
        logger.warning("Simulated cooling system activation")
    if pi_temperature is not None and pi_temperature > 75:
        logger.critical("Simulated system shutdown")

def setup_gpio():
    """Initialize GPIO pins as simulated input pins."""
    try:
        light_pin = gpiozero.RoboLinkAnalogInputDevice(17, pull_up=False)
        temperature_pin = gpiozero.RoboLinkAnalogInputDevice(4, pull_up=False)
        logger.info("GPIO pins initialized successfully")
        return light_pin, temperature_pin
    except Exception as e:
        logger.error(f"Failed to initialize GPIO pins: {e}")
        return None, None

def main():
    """Main function."""
    light_pin, temperature_pin = setup_gpio()
    if light_pin is None or temperature_pin is None:
        return

    while True:
        try:
            light = simulate_light_sensor(light_pin.pin_number)
            temperature = simulate_temperature_sensor(temperature_pin.pin_number)
            light_value = light.value
            temperature_value = temperature.value
            voltage = 11.5 + (light_value - 600) * 0.05 if light_value > 300 else 10.0 + (light_value - 100) * 0.05
            current = 1.5 + (light_value - 600) * 0.005 if light_value > 300 else 0.5 + (light_value - 100) * 0.005
            pi_temperature = read_pi_temperature()
            log_reading(light_value, temperature_value, voltage, current, pi_temperature)
            threshold_actions(light_value, temperature_value, voltage, current, pi_temperature)
            time.sleep(5)
        except KeyboardInterrupt:
            logger.info("Received keyboard interrupt, exiting")
        except Exception as e:
            logger.error(f"Error: {e}")
        finally:
            light_pin.close()
            temperature_pin.close()

if __name__ == '__main__':
    main()

