import smbus2
import time
import logging
import logging.handlers
import sys
import board
import busio
import adafruit_ads1x15
from adafruit_ads1x15.analog_in import AnalogIn
import picamera2
import paho.mqtt.client as mqtt
import gpiozero

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DHT20:
    def __init__(self, i2c_bus=1, address=0x38):
        try:
            self.i2c = smbus2.SMBus(i2c_bus)
        except smbus2.SMBusException as e:
            logger.error(f"Failed to open I2C bus {i2c_bus}: {e}")
            self.i2c = None
            return False

        time.sleep(0.5)  # Wait for power stabilization
        try:
            status = self.i2c.read_byte_data(address, 0x71)
        except smbus2.SMBusException as e:
            logger.error(f"Failed to read status from DHT20: {e}")
            self.i2c = None
            return False

        if (status & 0x18) != 0x18:
            logger.error("DHT20 status check failed")
            self.i2c = None
            return False

        self.address = address

    def get_temperature_and_humidity(self):
        if self.i2c is None:
            return None, None, True

        retry_count = 0
        while retry_count < 5:
            try:
                self.i2c.write_byte_data(self.address, 0xAC, 0x33)
            except smbus2.SMBusException as e:
                logger.error(f"Failed to trigger measurement: {e}")
                return None, None, True

            start_time = time.time()
            while True:
                try:
                    status = self.i2c.read_byte_data(self.address, 0x71)
                except smbus2.SMBusException as e:
                    logger.error(f"Failed to read status: {e}")
                    return None, None, True

                if not status & 0x80:
                    break
                if time.time() - start_time > 0.1:
                    logger.warning("Measurement timed out")
                    return None, None, True

            try:
                data = self.i2c.read_i2c_block_data(self.address, 0x71, 7)
            except smbus2.SMBusException as e:
                logger.error(f"Failed to read data: {e}")
                return None, None, True

            raw_H = (data[1] << 16) | (data[2] << 8) | data[3]
            raw_T = (data[3] >> 4) | (data[4] << 4) | (data[5] << 12)
            crc = data[6]

            if crc != self._calculate_crc(data[:6]):
                logger.warning("CRC failure, retrying")
                retry_count += 1
                continue

            temperature = raw_T / 5242.88 - 50
            humidity = raw_H / 1048576 * 100

            return temperature, humidity, False

        return None, None, True

    def _calculate_crc(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
        return crc

    def cleanup(self):
        if self.i2c is not None:
            self.i2c.close()

# Example usage
if __name__ == "__main__":
    dht20 = DHT20()
    if dht20:
        temperature, humidity, crc_error = dht20.get_temperature_and_humidity()
        if temperature is not None:
            print(f"Temperature: {temperature}°C, Humidity: {humidity}%")
        else:
            print("Failed to read temperature and humidity")
    else:
        print("Failed to initialize DHT20")
    dht20.cleanup()

