# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s: %(message)s')

class DHT20:
    def __init__(self, i2c_bus=1, i2c_address=0x38):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.smbus = None
        self.lock = threading.Lock()
        self.cache = None
        self.last_call_time = 0
        self.max_attempts = 5
        self.measurement_attempts = 0
        self.measurement_timeout = 0.8
        self.poll_interval = 0.08
        self.crc_polynomial = 0x31
        self.crc_initial = 0xFF

    def __enter__(self):
        self.begin()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def begin(self):
        try:
            self.smbus = smbus2.SMBus(self.i2c_bus)
        except OSError as e:
            logging.error(f"Failed to open I2C bus {self.i2c_bus}: {e}")
            return False

        time.sleep(0.5)  # Wait 0.5 seconds after power-on

        try:
            status = self.smbus.read_byte_data(self.i2c_address, 0x71)
        except OSError as e:
            logging.error(f"Failed to read status register 0x71: {e}")
            return False

        if (status & 0x18) != 0x18:
            logging.error("Invalid status register 0x71 value")
            return False

        return True

    def close(self):
        if self.smbus is not None:
            self.smbus.close()

    def get_temperature_and_humidity(self):
        with self.lock:
            if time.time() - self.last_call_time < 2:
                return self.cache

            if not self.begin():
                return (None, None, True)

            for attempt in range(self.max_attempts):
                try:
                    self.smbus.write_byte_data(self.i2c_address, 0xAC, 0x33)
                    self.smbus.write_byte_data(self.i2c_address, 0xAC, 0x00)
                except OSError as e:
                    logging.error(f"Failed to trigger measurement: {e}")
                    return (None, None, True)

                start_time = time.time()
                while True:
                    try:
                        status = self.smbus.read_byte_data(self.i2c_address, 0x71)
                    except OSError as e:
                        logging.warning(f"Timeout reading status register 0x71: {e}")
                        if attempt < self.max_attempts - 1:
                            time.sleep(self.poll_interval)
                            continue
                        else:
                            return (None, None, True)

                    if not status & 0x80:
                        break

                    if time.time() - start_time > self.measurement_timeout:
                        return (None, None, True)

                    time.sleep(self.poll_interval)

                try:
                    data = self.smbus.read_i2c_block_data(self.i2c_address, 0x00, 7)
                except OSError as e:
                    logging.error(f"Failed to read data: {e}")
                    return (None, None, True)

                crc = crccheck.crc8(self.crc_polynomial, self.crc_initial, data[5])
                if crc != 0xFF:
                    logging.warning(f"Invalid CRC: {crc}")
                    if attempt < self.max_attempts - 1:
                        continue
                    else:
                        return (None, None, True)

                raw_humidity = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
                humidity = raw_humidity / 2**20 * 100

                raw_temperature = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
                temperature = raw_temperature / 2**19 * 200 - 50

                self.cache = (temperature, humidity, False)
                self.last_call_time = time.time()
                return self.cache

            return (None, None, True)

