import gpiozero
import signal
import sys
import time
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)

# Define the pins and their corresponding sensor names
pins = {
    17: 'Sensor 1',
    27: 'Sensor 2',
    22: 'Sensor 3'
}

# Define the poll interval in seconds
poll_interval = 1

# Define a function to handle SIGTERM and KeyboardInterrupt
def signal_handler(sig, frame):
    logging.info('Received signal to exit')
    for pin in pins:
        try:
            pin_device.close()
        except gpiozero.DeviceNotFound:
            logging.warning(f'Failed to close pin {pin} device')
        except Exception as e:
            logging.error(f'Failed to close pin {pin} device: {e}')
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

# Initialize the GPIO pins with active-high pull-up resistors
try:
    pin_devices = {pin: gpiozero.DigitalInputDevice(pin=pin, pull_up=True) for pin in pins}
except gpiozero.DeviceNotFound as e:
    logging.error(f'Failed to initialize GPIO pins: {e}')
