import busio
import adafruit_tsl2561
import pigpio
import smbus2
import numpy as np

# Initialize the I2C bus
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    sys.exit(1)

# Initialize the TSL2561 sensor
try:
    sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=0x39)
    sensor.gain = adafruit_tsl2561.Gain.AUTO
except Exception as e:
    print(f"Error initializing TSL2561 sensor: {e}")
    sys.exit(1)

