    pi.set_mode(18, pigpio.OUTPUT)
    pi.hardware_PWM(18, 1000, 0)
except Exception as e:
    print(f"Error configuring GPIO18: {e}")
    sys.exit(1)

try:
    while True:
        # Read the lux value
        try:
            lux = sensor.lux
        except Exception as e:
            print(f"Error reading lux value: {e}")
            lux = None

        # Map the lux value to duty cycle
        if lux is None:
            duty = 0
        else:
            duty = np.clip(lux / 10, 0, 100)

        # Set the PWM duty cycle
        try:
            pi.hardware_PWM(18, 1000, int(duty * 1000000))
        except Exception as e:
            print(f"Error setting PWM duty cycle: {e}")

        # Wait for 1 second
        time.sleep(1)
except KeyboardInterrupt:
    # Stop the PWM
    try:
        pi.hardware_PWM(18, 0, 0)
    except Exception as e:
        print(f"Error stopping PWM: {e}")

# Release the pigpio connection
try:
    pi.stop()
except Exception as e:
    print(f"Error releasing pigpio connection: {e}")

print("Cleanup complete")

