import gpiozero
from gpiozero import Button
from gpiozero.pins.rpigpio import RPiGPIOFactory
from picamera2 import Picamera2
from adafruit_circuitpython_pca9685 import PCA9685
import paho.mqtt.client as mqtt
import time
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.prev_clk_state = None
        self.prev_dt_state = None

        # Create a GPIO factory
        gpiozero.pins.factory = RPiGPIOFactory()

        # Create GPIO pins with internal pull-up resistors
        self.clk_button = Button(self.clk_pin, pull_up=True, bounce_time=0.005)
        self.dt_button = Button(self.dt_pin, pull_up=True, bounce_time=0.005)

        # Validate callback
        if not callable(self.callback):
            raise ValueError("Callback must be a callable function")

        # Bind events to the buttons
        self.clk_button.when_pressed = self._on_clk_rising
        self.clk_button.when_released = self._on_clk_falling
        self.dt_button.when_pressed = self._on_dt_rising
        self.dt_button.when_released = self._on_dt_falling

    def _on_clk_rising(self):
        self._update_counter(1)

    def _on_clk_falling(self):
        self._update_counter(-1)

    def _on_dt_rising(self):
        if self.prev_clk_state == 1 and self.prev_dt_state == 0:
            self._update_counter(1)
        elif self.prev_clk_state == 0 and self.prev_dt_state == 1:
            self._update_counter(-1)

    def _on_dt_falling(self):
        if self.prev_clk_state == 1 and self.prev_dt_state == 0:
            self._update_counter(-1)
        elif self.prev_clk_state == 0 and self.prev_dt_state == 1:
            self._update_counter(1)

    def _update_counter(self, delta):
        self.counter += delta
        try:
            self.callback(self.counter)
        except Exception as e:
            logging.error(f"Error in callback: {e}")

    def cleanup(self):
        self.clk_button.close()
        self.dt_button.close()

def on_counter_change(counter):
    logging.info(f"Counter value: {counter}")

def main():
    try:
        encoder = RotaryEncoder(17, 18, on_counter_change)
        while True:
            time.sleep(0.1)
    except KeyboardInterrupt:
        encoder.cleanup()
        logging.info("Exiting...")
    finally:
        logging.info("Resources released")

if __name__ == "__main__":
    main()

import sys
import signal
import time
