logger = logging.getLogger(__name__)
handler = logging.StreamHandler(sys.stderr)
logger.addHandler(handler)

# Set up GPIO
gpiozero.Device.pin_factory = PiGPIOFactory()

# Set up touchpads
touchpad_a = Button(5)
touchpad_b = Button(6)
touchpad_c = Button(12)

# Set up LEDs
led_red = gpiozero.LED(7)
led_green = gpiozero.LED(8)
led_blue = gpiozero.LED(9)

# Set up display
try:
    display = HT16K33(i2c_address=0x70)
except Exception as e:
    logger.error(f"Failed to initialize display: {e}")
    display = None

# Set up LED strip
try:
    led_strip = APA102(10, 11, 1000)
except Exception as e:
    logger.error(f"Failed to initialize LED strip: {e}")
    led_strip = None

# Set up buzzer
buzzer = gpiozero.Buzzer(13)

# Set up MQTT client
try:
    client = mqtt.Client()
    client.connect("localhost")
except Exception as e:
    logger.error(f"Failed to connect to MQTT broker: {e}")
    client = None

# Set up bit states
bit_states = [False, False, False]

def signal_handler(sig, frame):
    logger.info("Received signal, shutting down")
    try:
        if display:
            display.off()
    except Exception as e:
        logger.error(f"Failed to turn off display: {e}")
    try:
        led_red.off()
        led_green.off()
        led_blue.off()
    except Exception as e:
        logger.error(f"Failed to turn off LEDs: {e}")
    try:
        if led_strip:
            led_strip.deinit()
    except Exception as e:
        logger.error(f"Failed to deinit LED strip: {e}")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def update_display():
    try:
        if display:
            display.show_number(int(''.join('01234567'[int(x)] for x in ['1' if x else '0' for x in bit_states]), 0)
    except Exception as e:
        logger.error(f"Failed to update display: {e}")

def update_led_strip():
    try:
        if led_strip:
            if int(''.join('01234567'[int(x)] for x in ['1' if x else '0' for x in bit_states])) == 0:
                led_strip.fill((0, 0, 0))
            elif int(''.join('01234567'[int(x)] for x in ['1' if x else '0' for x in bit_states])) == 7:
                led_strip.fill((255, 255, 255))
            else:
                color = (int('01'[int(bit_states[0])], 2) * 255, int('01'[int(bit_states[1])], 2) * 255, int('01'[int(bit_states[2])], 2) * 255)
                led_strip.fill((0, 0, 0))
                led_strip[0] = color
    except Exception as e:
        logger.error(f"Failed to update LED strip: {e}")

def play_tone():
    try:
        if client:
            client.publish("tone", int(''.join('01234567'[int(x)] for x in ['1' if x else '0' for x in bit_states]) + 60))
    except Exception as e:
        logger.error(f"Failed to publish tone: {e}")
    try:
        if buzzer:
            buzzer.play(int(''.join('01234567'[int(x)] for x in ['1' if x else '0' for x in bit_states]) + 60, 'm')
    except Exception as e:
        logger.error(f"Failed to play tone: {e}")

def main():
    while True:
        try:
            if touchpad_a.value:
                bit_states[2] = not bit_states[2]
            if touchpad_b.value:
                bit_states[1] = not bit_states[1]
            if touchpad_c.value:
                bit_states[0] = not bit_states[0]
            update_display()
            update_led_strip()
            play_tone()
            time.sleep(0.5)
        except Exception as e:
            logger.error(f"Failed to process touch event: {e}")
        signal.pause()

if __name__ == "__main__":
    main()

