import logging
import signal
import sys
import time
import atexit
import board
import busio
import adafruit_motor
from adafruit_motor import Motor
from adafruit_motor import MotorHAT
from adafruit_motor import PWM
from gpiozero import LED
from picamera2 import Picamera2
from paho.mqtt.client import Client as MQTTClient
import RPi.GPIO as GPIO

# Set up logging
logging.basicConfig(level=logging.INFO)

class DCMotorHATExtra(MotorHAT):
    def __init__(self):
        super().__init__(address=0x60, bus=1)
        self.i2c = busio.I2C(board.SCL1, board.SDA1)
        try:
            self.i2c.try_lock()
            self.i2c.writeto(0x60, b'\x00\x00')
            self.i2c.unlock()
        except Exception as e:
            logging.error(f"I2C initialization failed: {e}")
            raise
        self.pwm_freq = 60
        self.motors = [None, None, None, None]
        self.atexit_handler = atexit.register(self.release_all_motors)
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def set_pwm_freq(self, freq):
        self.pwm_freq = freq

    def get_pwm_freq(self):
        return self.pwm_freq

    def release_all_motors(self):
        for motor in self.motors:
            if motor:
                motor.release()

    def signal_handler(self, sig, frame):
        self.release_all_motors()
        sys.exit(0)

class DCMotor:
    def __init__(self, hat, motor_number, pwm_freq=None, invert=False):
        if motor_number < 1 or motor_number > 4:
            raise ValueError("Invalid motor number")
        self.hat = hat
        self.motor_number = motor_number
        self.pwm_freq = pwm_freq if pwm_freq else hat.get_pwm_freq()
        self.invert = invert
        self.last_duty_cycle = 0
        self.motor = None
        try:
            self.motor = Motor(self.hat, motor_number, pwm_freq=self.pwm_freq, invert=self.invert)
        except Exception as e:
            logging.error(f"Failed to initialize motor {motor_number}: {e}")

    def set_dc(self, duty_cycle):
        if duty_cycle < -255 or duty_cycle > 255:
            logging.warning(f"Duty cycle out of range: {duty_cycle}, clamping to [-255, 255]")
            duty_cycle = max(-255, min(duty_cycle, 255))
        if duty_cycle == 0:
            self.motor.release()
        else:
            direction = (duty_cycle < 0) ^ self.invert
            self.motor.setSpeed(abs(duty_cycle))
            self.motor.setDirection(direction)
        self.last_duty_cycle = duty_cycle

    def stop(self):
        self.motor.release()

    def close(self):
        self.stop()
        self.motor = None

    def get_status(self):
        return {
            "motor_number": self.motor_number,
            "pwm_freq": self.pwm_freq,
            "invert": self.invert,
            "last_duty_cycle": self.last_duty_cycle
        }

def main():
    hat = DCMotorHATExtra()
    motor = DCMotor(hat, 1)
    try:
        for i in range(256):
            motor.set_dc(i)
            time.sleep(0.01)
        for i in range(255, -1, -1):
            motor.set_dc(i)
            time.sleep(0.01)
    finally:
        motor.close()

if __name__ == "__main__":
    main()

