    'Register': 0x3500,
    'functioncode': 6,
    'Value': {
        'Position': 1
    }
}

VelocityFeedback = {
    'R/W': 'R',
    'Register': 0x3B00,
    'functioncode': 3,
    'read_length': 2
}

PositionFeedback = {
    'R/W': 'R',
