    'functioncode': 3,
    'read_length': 2
}

PositionCommand = {
    'R/W': 'W',
    'Register': 0x4000,
    'functioncode': 16,
    'Value': {
        'Position': 0
    }
}

VelocityCommand = {
    'R/W': 'W',
    'Register': 0x6F00,
    'functioncode': 16,
    'Value': {
        'Velocity': 0
    }
}

class Servo:
    def __init__(self, servo_pin, servo_min=0.5, servo_max=12.5):
        self.servo_pin = servo_pin
        self.servo_min = servo_min
        self.servo_max = servo_max
        self.servo = Servo(self.servo_pin, min_pulse=1000, max_pulse=2000)
        self.client = None
        self.pca = None
        self.camera = None
        self.mqtt_client = None
        self.register_map = {
            CONTROL['Register']: CONTROL,
            OPMODE['Register']: OPMODE,
            VelocityFeedback['Register']: VelocityFeedback,
            PositionFeedback['Register']: PositionFeedback,
            PositionCommand['Register']: PositionCommand,
            VelocityCommand['Register']: VelocityCommand
        }

    def _connect_modbus(self):
        try:
            self.client = ModbusClient('localhost', 1700)
            self.client.connect()
        except (ConnectionException, ModbusIOException) as e:
            logger.warning(f"Failed to connect to Modbus device: {e}")

    def _connect_pca(self):
        try:
            self.pca = PCA9685(0x40)
            self.pca.frequency = 60
        except Exception as e:
            logger.warning(f"Failed to connect to PCA9685: {e}")

    def _connect_camera(self):
        try:
            self.camera = Picamera2()
        except Exception as e:
            logger.warning(f"Failed to connect to camera: {e}")

    def _connect_mqtt(self):
        try:
            self.mqtt_client = mqtt.Client()
            self.mqtt_client.connect("localhost")
        except Exception as e:
            logger.warning(f"Failed to connect to MQTT broker: {e}")

    def _disconnect_modbus(self):
        if self.client:
            self.client.close()

    def _disconnect_pca(self):
        if self.pca:
            self.pca.deinit()

    def _disconnect_camera(self):
        if self.camera:
            self.camera.close()

    def _disconnect_mqtt(self):
        if self.mqtt_client:
            self.mqtt_client.disconnect()

    def _write_register(self, register, value):
        try:
            if self.client:
                result = self.client.write_register(register, value, unit=1)
                if result.isError():
                    logger.error(f"Failed to write to register {register}: {result}")
            else:
                logger.warning(f"Modbus client not connected")
        except (ConnectionException, ModbusIOException) as e:
            logger.error(f"Failed to write to register {register}: {e}")

    def _read_registers(self, register, count):
        try:
            if self.client:
                result = self.client.read_holding_registers(register, count, unit=1)
                if result.isError():
                    logger.error(f"Failed to read from register {register}: {result}")
                return result.registers
            else:
                logger.warning(f"Modbus client not connected")
        except (ConnectionException, ModbusIOException) as e:
            logger.error(f"Failed to read from register {register}: {e}")

    def _set_servo_position(self, position):
        self.servo.value = position

    def _set_servo_velocity(self, velocity):
        self._write_register(VelocityCommand['Register'], velocity)

    def _get_servo_position(self):
        return self._read_registers(PositionFeedback['Register'], PositionFeedback['read_length'])[0]

    def _get_servo_velocity(self):
        return self._read_registers(VelocityFeedback['Register'], VelocityFeedback['read_length'])[0]

    def _set_opmode(self, opmode):
        self._write_register(OPMODE['Register'], opmode)

    def _get_opmode(self):
        return self._read_registers(OPMODE['Register'], 1)[0]

    def _start(self):
        self._connect_modbus()
        self._connect_pca()
        self._connect_camera()
        self._connect_mqtt()
        self._set_opmode(OPMODE['Value']['Position'])
        self._set_servo_position(0)
        self._set_servo_velocity(0)

    def _stop(self):
        self._disconnect_modbus()
        self._disconnect_pca()
        self._disconnect_camera()
        self._disconnect_mqtt()

    def run(self):
        try:
            self._start()
            while True:
                # Read servo position and velocity
                position = self._get_servo_position()
                velocity = self._get_servo_velocity()
                # Publish to MQTT topic
                self.mqtt_client.publish("servo/position", str(position))
                self.mqtt_client.publish("servo/velocity", str(velocity))
                # Update servo position
                self._set_servo_position(position + 0.1)
                # Sleep for 100ms
                time.sleep(0.1)
        except KeyboardInterrupt:
            self._stop()
        except Exception as e:
            self._stop()
            logger.error(f"Error: {e}")

def signal_handler(sig, frame):
    logger.info("Exiting...")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

