class ServoMotor:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.serial = None
        self.modbus = None
        self.is_running = False

    def _open_serial(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=1)
            logger.info(f"Serial port {self.port} opened successfully")
        except serial.SerialException as e:
            logger.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def _close_serial(self):
        if self.serial:
            self.serial.close()
            logger.info(f"Serial port {self.port} closed")
            self.serial = None

    def _open_modbus(self):
        try:
            self.modbus = ModbusMaster(self.serial, slaveaddress=self.slave_address, timeout=1)
            logger.info(f"Modbus connection established to slave address {self.slave_address}")
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to connect to Modbus slave address {self.slave_address}: {e}")
            raise
        except minimalmodbus.InvalidResponseError as e:
            logger.error(f"Invalid response from Modbus slave address {self.slave_address}: {e}")
            raise

    def _close_modbus(self):
        if self.modbus:
            self.modbus.close()
            logger.info(f"Modbus connection closed")
            self.modbus = None

    def set_operation_mode(self, mode):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        if not isinstance(mode, int) or mode < 0 or mode > 3:
            raise ValueError("Invalid operation mode")
        try:
            self.modbus.write_register(0x3500, mode)
            logger.info(f"Operation mode set to {mode}")
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to set operation mode: {e}")
            raise

    def write_position_command(self, value):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        if not isinstance(value, int) or value < -180 or value > 180:
            raise ValueError("Invalid position value")
        try:
            self.modbus.write_register(0x4000, value)
            logger.info(f"Position command set to {value}")
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to set position command: {e}")
            raise

    def write_velocity_command(self, value):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        if not isinstance(value, int) or value < -100 or value > 100:
            raise ValueError("Invalid velocity value")
        try:
            self.modbus.write_register(0x6F00, value)
            logger.info(f"Velocity command set to {value}")
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to set velocity command: {e}")
            raise

    def read_position_feedback(self):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        try:
            position = self.modbus.read_holding_registers(0x3700, 2)
            logger.info(f"Position feedback: {position}")
            return position
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to read position feedback: {e}")
            raise

    def read_velocity_feedback(self):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        try:
            velocity = self.modbus.read_holding_registers(0x3B00, 2)
            logger.info(f"Velocity feedback: {velocity}")
            return velocity
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to read velocity feedback: {e}")
            raise

    def start(self):
        if self.is_running:
            raise ValueError("Servo motor is already running")
        try:
            self.modbus.write_register(0x3100, 0x000F)
            logger.info("Servo motor started")
            self.is_running = True
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to start servo motor: {e}")
            raise

    def stop(self):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        try:
            self.modbus.write_register(0x3100, 0x0006)
            logger.info("Servo motor stopped")
            self.is_running = False
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to stop servo motor: {e}")
            raise

    def read_status(self):
        if not self.is_running:
            raise ValueError("Servo motor is not running")
        try:
            status = self.modbus.read_holding_registers(0x3000, 1)
            logger.info(f"Servo motor status: {status}")
            return status
        except minimalmodbus.NoResponseError as e:
            logger.error(f"Failed to read servo motor status: {e}")
            raise

def signal_handler(sig, frame):
    logger.info("Received signal to exit")
    try:
        motor.stop()
        motor._close_modbus()
        motor._close_serial()
    except Exception as e:
        logger.error(f"Error during cleanup: {e}")
