    if not (0 <= servo_num <= 15):
        raise ValueError("Servo number must be 0-15")
    kit.servo[servo_num].angle = 90

def release_object(kit, servo_num=0):
    """Moves servo channel 0 to 150 degrees."""
    if not (0 <= servo_num <= 15):
        raise ValueError("Servo number must be 0-15")
    kit.servo[servo_num].angle = 150

def move_servo(kit, servo_num, target_angle):
    """Smoothly moves the servo in 5-degree increments with a 0.04-second delay between each step."""
    if not (0 <= servo_num <= 15):
        raise ValueError("Servo number must be 0-15")
    if not (0 <= target_angle <= 180):
        raise ValueError("Target angle must be 0-180 degrees")
    current_angle = kit.servo[servo_num].angle
    while current_angle != target_angle:
        if current_angle < target_angle:
            kit.servo[servo_num].angle = min(current_angle + 5, target_angle)
        else:
            kit.servo[servo_num].angle = max(current_angle - 5, target_angle)
