import smbus2
import time
import signal
import datetime
import logging
import sys

# Set up logging
logging.basicConfig(level=logging.INFO)

class DS1338RTC:
    def __init__(self, bus=1, address=0x68):
        self.bus = smbus2.SMBus(bus)
        self.address = address
        self.verify_device()

    def verify_device(self):
        try:
            self.bus.read_byte_data(self.address, 0x00)
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to verify device: {e}")
            sys.exit(1)

    def _bcd_to_int(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _int_to_bcd(self, value):
        return (value // 10) << 4 | (value % 10)

    def read_seconds(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x00))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read seconds: {e}")
            return None

    def write_seconds(self, value):
        try:
            self.bus.write_byte_data(self.address, 0x00, self._int_to_bcd(value))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to write seconds: {e}")

    def read_minutes(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x01))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read minutes: {e}")
            return None

    def write_minutes(self, value):
        try:
            self.bus.write_byte_data(self.address, 0x01, self._int_to_bcd(value))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to write minutes: {e}")

    def read_hours(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x02)) & 0x1F
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read hours: {e}")
            return None

    def write_hours(self, value):
        try:
            self.bus.write_byte_data(self.address, 0x02, self._int_to_bcd(value & 0x1F))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to write hours: {e}")

    def read_date(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x04))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read date: {e}")
            return None

    def write_date(self, value):
        try:
            self.bus.write_byte_data(self.address, 0x04, self._int_to_bcd(value))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to write date: {e}")

    def read_month(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x05))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read month: {e}")
            return None

    def write_month(self, value):
        try:
            self.bus.write_byte_data(self.address, 0x05, self._int_to_bcd(value))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to write month: {e}")

    def read_year(self):
        try:
            return 2000 + self._bcd_to_int(self.bus.read_byte_data(self.address, 0x06))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read year: {e}")
            return None

    def write_year(self, value):
        try:
            self.bus.write_byte_data(self.address, 0x06, self._int_to_bcd(value % 100))
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to write year: {e}")

    def read_datetime(self, century=21):
        try:
            seconds = self.read_seconds()
            minutes = self.read_minutes()
            hours = self.read_hours()
            date = self.read_date()
            month = self.read_month()
            year = self.read_year()
            return datetime.datetime(century * 100 + year, month, date, hours, minutes, seconds)
        except (OSError, smbus2.SMBusException) as e:
            logging.error(f"Failed to read datetime: {e}")
            return None

    def write_all(self, year=None, month=None, date=None, hours=None, minutes=None, seconds=None):
        if year is not None and not 0 <= year <= 99:
            logging.error("Invalid year")
            return
        if month is not None and not 1 <= month <= 12:
            logging.error("Invalid month")
            return
        if date is not None and not 1 <= date <= 31:
            logging.error("Invalid date")
            return
        if hours is not None and not 0 <= hours <= 23:
            logging.error("Invalid hours")
            return
        if minutes is not None and not 0 <= minutes <= 59:
            logging.error("Invalid minutes")
            return
        if seconds is not None and not 0 <= seconds <= 59:
            logging.error("Invalid seconds")
            return
        self.write_year(year or self.read_year())
        self.write_month(month or self.read_month())
        self.write_date(date or self.read_date())
        self.write_hours(hours or self.read_hours())
        self.write_minutes(minutes or self.read_minutes())
        self.write_seconds(seconds or self.read_seconds())

    def __del__(self):
        self.bus.close()

def signal_handler(sig, frame):
    logging.info("Exiting...")
    rtc = DS1338RTC()
    rtc.bus.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    rtc = DS1338RTC()
    while True:
        try:
            dt = rtc.read_datetime()
            print(dt)
            time.sleep(1)
        except KeyboardInterrupt:
            break
    del rtc

