import sys
import signal
import serial
import time
import re
import logging
from gpiozero import DigitalInputDevice, DigitalOutputDevice
from picamera2 import Picamera2
from adafruit_circuitpython_pca9685 import PCA9685
from paho.mqtt.client import Client as MQTTClient
import threading

# Set up logging
logging.basicConfig(level=logging.INFO)

class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        try:
            self.serial = serial.Serial(port, baud_rate, timeout=timeout)
            self.serial.flushInput()
            self.serial.flushOutput()
            logging.info(f"Serial port {port} opened at {baud_rate} baud")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {port}: {e}")
            sys.exit(1)

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        try:
            self.serial.write(command.encode())
            self.serial.write(b'\r\n')
            response = b''
            start_time = time.time()
            while time.time() - start_time < timeout:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                    if wait_for in response:
                        return response
                time.sleep(0.01)
            logging.error(f"Timeout waiting for response to {command}")
            return None
        except serial.SerialException as e:
            logging.error(f"Error sending command {command}: {e}")
            return None

    def test_connection(self):
        response = self._send_command(b'AT', timeout=1.0, wait_for=b'OK')
        if response is None:
            return False
        return b'OK' in response

    def restart(self):
        response = self._send_command(b'AT+RST', timeout=10.0, wait_for=b'ready')
        if response is None:
            return False
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        response = self._send_command(f'AT+CWJAP="{ssid}","{password}"'.encode(), timeout=10.0, wait_for=b'OK')
        if response is None:
            return False
        return b'OK' in response

    def disconnect_wifi(self):
        response = self._send_command(b'AT+CWQAP', timeout=1.0, wait_for=b'OK')
        if response is None:
            return False
        return b'OK' in response

    def get_ip(self):
        response = self._send_command(b'AT+CIFSR', timeout=1.0, wait_for=b'STAT')
        if response is None:
            return None
        match = re.search(b'STAT: IPD,STAIP,(\d+\.\d+\.\d+\.\d+)', response)
        if match:
            return match.group(1).decode()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        try:
            self._send_command(f'AT+CIPSTART="TCP","{host}",{port}'.encode(), timeout=10.0, wait_for=b'CONNECT')
            if headers is not None:
                for key, value in headers.items():
                    self._send_command(f'AT+CIPHEADER="{key}","{value}"'.encode(), timeout=1.0, wait_for=b'OK')
            if data is not None:
                self._send_command(f'AT+CIPSEND={len(data)}'.encode(), timeout=1.0, wait_for=b'>')
                self.serial.write(data)
                self.serial.write(b'\r\n')
            self._send_command(b'AT+CIPSEND'.encode(), timeout=1.0, wait_for=b'>')
            response = self._send_command(b'', timeout=10.0, wait_for=b'+IPD')
            if response is None:
                return None
            match = re.search(b'+IPD,(\d+):(.*)', response)
            if match:
                length, payload = int(match.group(1)), match.group(2)
                return payload
            return None
        except serial.SerialException as e:
            logging.error(f"Error sending HTTP request: {e}")
            return None

    def receive_http_response(self, timeout=5.0):
        try:
            response = b''
            start_time = time.time()
            while time.time() - start_time < timeout:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                    if b'CLOSED' in response:
                        return None
                time.sleep(0.01)
            logging.error(f"Timeout waiting for HTTP response")
            return None
        except serial.SerialException as e:
            logging.error(f"Error receiving HTTP response: {e}")
            return None

def signal_handler(sig, frame):
    if hasattr(esp, 'serial'):
        esp.serial.close()
    sys.exit(0)

def main():
    global esp
    esp = ESP8266Controller()
    if not esp.test_connection():
        logging.error("Failed to connect to ESP8266")
        sys.exit(1)
    logging.info("Connected to ESP8266")
    try:
        while True:
            command = input("Enter a command (test, restart, connect_wifi, disconnect_wifi, get_ip, send_http_request, receive_http_response): ")
            if command == 'test':
                print(esp.test_connection())
            elif command == 'restart':
                print(esp.restart())
            elif command == 'connect_wifi':
                ssid = input("Enter SSID: ")
                password = input("Enter password: ")
                print(esp.connect_wifi(ssid, password))
            elif command == 'disconnect_wifi':
                print(esp.disconnect_wifi())
            elif command == 'get_ip':
                print(esp.get_ip())
            elif command == 'send_http_request':
                method = input("Enter method (GET, POST, PUT, DELETE): ")
                url = input("Enter URL: ")
                host = input("Enter host: ")
                port = int(input("Enter port (default 80): ") or 80)
                headers = {}
                for i in range(int(input("Enter number of headers: ")) or 0):
                    key = input(f"Enter header {i+1} key: ")
                    value = input(f"Enter header {i+1} value: ")
                    headers[key] = value
                data = input("Enter data (empty for none): ")
                print(esp.send_http_request(method, url, host, port, headers, data))
            elif command == 'receive_http_response':
                print(esp.receive_http_response())
            else:
                print("Unknown command")
    except KeyboardInterrupt:
        signal_handler(None, None)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    main()

