            return None
        try:
            data = self.serial_port.readline().decode('utf-8', errors='ignore').strip()
            return data
        except serial.SerialException as e:
            logging.error(f'Failed to read from GPS device: {e}')
            return None

    def parse_gga(self, sentence):
        try:
            talker_id = sentence[1:3]
            if talker_id not in ['GPGGA', 'GNGGA']:
                return None
            parts = sentence.split(',')
            if len(parts) < 13:
                return None
            utc_time = parts[1]
            latitude = parts[2]
            if latitude[0] == '0':
                latitude = None
            else:
                latitude = np.deg2rad(np.radians(float(latitude)))
            longitude = parts[4]
            if longitude[0] == '0':
                longitude = None
            else:
                longitude = np.deg2rad(np.radians(float(longitude)))
            fix_quality = parts[6]
            num_satellites = parts[7]
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except IndexError as e:
            logging.error(f'Failed to parse GGA sentence: {e}')
            return None
        except ValueError as e:
            logging.error(f'Failed to parse GGA sentence: {e}')
            return None

    def close(self):
        if self.serial_port:
            try:
                self.serial_port.close()
            except serial.SerialException as e:
                logging.error(f'Failed to close serial port: {e}')
            self.serial_port = None
            self.connected = False

