class SerialCommunicator:
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.serial = None

    def __enter__(self):
        with serial_lock:
            try:
                self.serial = serial.Serial(self.port, self.baudrate, timeout=1)
            except serial.SerialException as e:
                logging.error(f"Failed to open serial port: {e}")
                raise
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial:
            self.serial.close()

    def send(self, cmd):
        encoded_cmd = cmd.encode('ascii')
        self.serial.write(encoded_cmd)
        response = self.serial.read(len(encoded_cmd))
        if len(response) != len(encoded_cmd):
            logging.error("Invalid response length")
            raise serial.SerialException("Invalid response length")
        self.serial.flush()

    def receive_line(self):
        try:
            return self.serial.readline().decode('ascii').strip()
        except serial.SerialException as e:
            logging.error(f"Failed to read from serial port: {e}")
            raise
        except UnicodeDecodeError:
            return None

    def close(self):
        with serial_lock:
            if self.serial:
                self.serial.close()

class DataManager:
    def __init__(self):
        self.data = []
        self.id_counter = 1
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return self.data

    def get_by_id(self, id):
        with self.lock:
            for item in self.data:
                if item['id'] == id:
                    return item
            return None

    def create(self, name, done):
        if not name or not isinstance(done, bool):
            return None
        with self.lock:
            item = {'id': self.id_counter, 'name': name, 'done': done}
            self.data.append(item)
            self.id_counter += 1
            return item

