        if len(response) != len(encoded_cmd):
            logging.error("Invalid response length")
            raise serial.SerialException("Invalid response length")
        self.serial.flush()

    def receive_line(self):
        try:
            return self.serial.readline().decode('ascii').strip()
        except serial.SerialException as e:
            logging.error(f"Failed to read from serial port: {e}")
            raise
        except UnicodeDecodeError:
            return None

    def close(self):
        with serial_lock:
            if self.serial:
                self.serial.close()

class DataManager:
    def __init__(self):
        self.data = []
        self.id_counter = 1
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return self.data

    def get_by_id(self, id):
        with self.lock:
            for item in self.data:
                if item['id'] == id:
                    return item
            return None

    def create(self, name, done):
        if not name or not isinstance(done, bool):
            return None
        with self.lock:
            item = {'id': self.id_counter, 'name': name, 'done': done}
            self.data.append(item)
            self.id_counter += 1
            return item

app = Flask(__name__)

@app.route('/version', methods=['GET'])
def get_version():
    try:
        with SerialCommunicator('/dev/ttyUSB0', 9600) as sc:
            sc.send('*IDN?')
            response = sc.receive_line()
            if response is None:
                return 'Timeout', 504
            return response, 200, {'Content-Type': 'text/plain'}
    except serial.SerialException:
        return 'Failed to open serial port', 502
    finally:
        sc.close()

@app.route('/data', methods=['GET'])
def get_data():
    return jsonify(DataManager().get_all()), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_item(item_id):
    item = DataManager().get_by_id(item_id)
    if item:
        return jsonify(item), 200
    return '', 404

@app.route('/data', methods=['POST'])
def create_item():
    data = request.json
    if 'name' not in data or 'done' not in data:
        return 'Invalid request', 400
    item = DataManager().create(data['name'], data['done'])
    if item:
        return jsonify(item), 201
    return 'Invalid request', 400

def signal_handler(sig, frame):
    app.logger.info('Received signal, shutting down')
    with SerialCommunicator('/dev/ttyUSB0', 9600) as sc:
        sc.close()
    app.logger.info('Serial port closed')
    app.logger.info('Stopping server')
    app.logger.info('Server stopped')
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)
```

This code sets up a Flask application that manages an in-memory data store and communicates with a USB-serial instrument on /dev/ttyUSB0 at 9600 baud. It implements the SerialCommunicator class to handle serial communication, and the DataManager class to manage the in-memory data store. The application has routes for getting the device's version, getting all data, getting a specific item, and creating a new item. The application also handles SIGINT and SIGTERM signals to close the serial port and stop the server.

