def read_pulse_oximeter_data():
    try:
        # Open the serial port
        with serial.Serial('/dev/ttyUSB0', 9600, timeout=1) as ser:
            while True:
                try:
                    # Read a line from the serial port
                    line = ser.readline().decode('ascii', errors='replace')
                    if line:
                        # Split the line into heart rate and SpO2
                        try:
                            heart_rate, spo2 = line.strip().split(',')
                            if len(heart_rate) > 0 and len(spo2) > 0:
