import serial
import time
import sys

def send_command(serial_connection, command):
    """Send a command to the connected device."""
    try:
        command = f"X{command}\n"
        serial_connection.write(command.encode())
        time.sleep(0.1)  # Introduce a 0.1 second delay
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

def main():
    try:
        # Establish a serial connection to the Bluetooth device
        serial_connection = serial.Serial('/dev/rfcomm4', 38400, timeout=1)
        print("Connected to Bluetooth device.")

        while True:
            # Prompt the user for a command
            user_input = input("Enter a command (or 'exit' to quit): ")

            if user_input.lower() == 'exit':
                break

            try:
                send_command(serial_connection, user_input)
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except serial.SerialException as e:
        print(f"Failed to establish serial connection: {e}")
    except KeyboardInterrupt:
        print("\nReceived keyboard interrupt, exiting...")
    finally:
        # Close the serial connection
        if 'serial_connection' in locals() and serial_connection.is_open:
            serial_connection.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    main()

